#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
#
# PostToolUse hook: format the file Claude just edited.
# Silent no-op when the formatter isn't installed yet, so it's safe pre-foundation.
# Never blocks the edit: always exits 0.

set -u

file_path="$(python3 -c 'import json,sys; print(json.load(sys.stdin).get("tool_input",{}).get("file_path",""))' 2>/dev/null)"
[ -n "$file_path" ] && [ -f "$file_path" ] || exit 0

root="${CLAUDE_PROJECT_DIR:-$(pwd)}"

case "$file_path" in
  */packages/types/src/generated/*) exit 0 ;; # generated by ts-rs, never touched
  *.rs)
    command -v rustfmt >/dev/null 2>&1 && rustfmt --edition 2024 --quiet "$file_path" 2>/dev/null
    ;;
  *.ts|*.tsx|*.js|*.jsx|*.json|*.css)
    biome="$root/node_modules/.bin/biome"
    [ -x "$biome" ] && "$biome" format --write --no-errors-on-unmatched "$file_path" >/dev/null 2>&1
    ;;
esac

exit 0
